(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.015+t*0.32)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.022-t*0.45)*8 + Math.cos(my*0.019+t*0.38)*6;
  const w2y = Math.cos(my*0.02+t*0.42)*8 + Math.sin(mx*0.017-t*0.5)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.85+1)*45, 0.085, 1.8, 1.15]
  ];
  let aS=0, iS=0, totalW=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const pulse = 1.0+Math.sin(t*sp*1.3)*0.15;
    aS += (Math.sin(d*f*1.2-t*sp*pulse)+Math.sin(d*f*0.6-t*sp*0.7+0.8))*0.5*w;
    iS += (Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.cos(d*f*0.4+t*sp*0.9-0.5))*0.5*w;
    totalW += w;
  }
  const act=aS/totalW, inh=iS/totalW;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15
    + Math.sin(sx*0.08+sy*0.06-t*1.8)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.07-ang*2+t*0.9)*0.6)*0.3;
  const lap = (Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx-5)*0.2)*Math.sin(sy*0.2)
    +Math.sin(sx*0.2)*Math.sin((sy-5)*0.2)+Math.sin((sx+5)*0.2)*Math.sin(sy*0.2)
    +Math.sin(sx*0.2)*Math.sin((sy+5)*0.2)-4*Math.sin(sx*0.2)*Math.sin(sy*0.2))*0.3;
  const react = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + lap)*2.0);
  const fine = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.15;
  const contour = Math.abs(react)>0.15 && Math.abs(react)<0.35 ? 0.12 : 0;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.2;
  const blend = react*0.7 + cell*0.15 + fine*0.1 + contour;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,35,88],[12,65,115],[18,105,130],[25,148,138],
    [85,175,110],[175,190,75],[215,165,55],[220,125,65],[195,75,70],
    [145,42,75],[85,22,65],[35,14,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(react*Math.PI)*0.18;
  const edge=(Math.abs(react)>0.6?1.12:1.0)*(contour>0?1.08:1.0);
  const shimmer=Math.sin(ang*6+dist*0.08-t*2)*0.04;
  return [
    Math.min(255,Math.max(0,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+shimmer*40)|0)),
    Math.min(255,Math.max(0,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+shimmer*30)|0)),
    Math.min(255,Math.max(0,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+shimmer*20)|0))
  ];
}
